contract InvMutTest {
    C c;

    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    function run(uint amount, uint extra) public payable {
        require(amount <= address(c).balance);

        uint balanceBefore = address(c).balance;

        c.withdraw(amount); if (__ESBMC_reverted()) return;

        assert(address(c).balance == balanceBefore - amount);
    }

    receive() external payable {}
}

