pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {SimpleWallet} from "../src/SimpleWallet.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    SimpleWallet c;

    function setUp() public {
        c = new SimpleWallet();
    }

    function _run(uint256 amount, uint256 extra) internal {
        vm.assume(amount <= address(c).balance);
        uint balanceBefore = address(c).balance;
        try c.withdraw(amount) {} catch { return; }
        assertTrue(address(c).balance == balanceBefore - amount);
    }

    function testFuzz_run(uint256 amount, uint256 extra) public {
        _run(amount, extra);
    }

    receive() external payable {}
}
